(7694366, 1261412, 143116, '<td valign="top">How things decay always fascinates me, like here.</td>', 'How things decay always fascinates me, like here.', '2021-05-16 13:52:28.000000', NULL, 1),
(7694434, 1261366, 143116, '<td valign="top">I like the textures that show up so nicely in the B&amp;W conversion! But the subject of the photograph remains a bit unclear to me - is it the fences on the right? the American flag? the beheaded tower, maybe? I guess it must be the wall.</td>', 'I like the textures that show up so nicely in the B&W conversion! But the subject of the photograph remains a bit unclear to me - is it the fences on the right? the American flag? the beheaded tower, maybe? I guess it must be the wall.', '2021-05-17 16:47:54.000000', NULL, 1),
(7694435, 1261410, 143116, '<td valign="top">Interesting how nature always seems to find a way. The shallow DoF does disorient me a bit, however.</td>', 'Interesting how nature always seems to find a way. The shallow DoF does disorient me a bit, however.', '2021-05-17 16:49:36.000000', NULL, 1),
(7694436, 1261405, 143116, '<td valign="top">Those classic cars were a piece of art indeed - nicely captured!</td>', 'Those classic cars were a piece of art indeed - nicely captured!', '2021-05-17 16:50:55.000000', NULL, 1),
(7694437, 1261237, 143116, '<td valign="top">In this case, the façade is already a piece of art!</td>', 'In this case, the façade is already a piece of art!', '2021-05-17 16:52:30.000000', NULL, 1),
(7694438, 1261400, 143116, '<td valign="top">Wow, what textures you''ve captured here.</td>', 'Wow, what textures you''ve captured here.', '2021-05-17 16:53:55.000000', NULL, 1),
