(7694532, 1261412, 3306, '<td valign="top">Great textures, colors and depth. The lighting and shadows add drama. Well done.</td>', 'Great textures, colors and depth. The lighting and shadows add drama. Well done.', '2021-05-19 07:17:06.000000', NULL, 0),
(7694533, 1261237, 3306, '<td valign="top">One of my favorites of the challenge. I like that the structure is identifiable and yet the composition is an implied abstract. The lighting adds intrigue.</td>', 'One of my favorites of the challenge. I like that the structure is identifiable and yet the composition is an implied abstract. The lighting adds intrigue.', '2021-05-19 07:19:30.000000', NULL, 0),
